            // changes, so reapply the requested VSync setting after the switch.
            VSyncEnabled = SDL.SetRenderVSync(
                renderer,
                AppSettings.Current.VSync ? 1 : 0
                );

            lock (frameLock)
            {
                resetLastBuffer();
                frameDirty = true;
            }
